const fr=(i)=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const style=P.style;
const amt=clp(P.amount,0,1), en=clp(P.energy,0,1), spd=clp(P.speed,.1,6), dens=clp(P.density,0,1), sc=clp(P.scale,.3,2);
const cx=P.x*W, cy=P.y*Hh, act=P.act;
const isGlitch=style==='glitch', isSeismic=style==='seismic', isFlash=style==='flashbulb', isXray=style==='xray';

if(S.ox==null){ S.ox=0; S.oy=0; S.vx=0; S.vy=0; S.tp=K.t; S.lastBar=Math.floor(K.bar); S.lastB2=Math.floor(K.beat); S.cd=0; S.rings=[]; }
let dt=K.t-S.tp; if(!(dt>0)||dt>0.2) dt=1/60; S.tp=K.t;

const stiff=110*spd, damp=13*Math.sqrt(spd), maxo=u*0.085*amt*sc+2;
function jolt(mag,dir){ const a=dir!=null?dir:fr(Math.floor(K.t*13)+mag*7)*TAU; const kick=u*3.2*mag*amt*sc; S.vx+=Math.cos(a)*kick; S.vy+=Math.sin(a)*kick; S.rings.push({x:cx,y:cy,r:u*0.02,mag:mag,life:1}); if(S.rings.length>7)S.rings.shift(); }

// clock-driven baseline jolts (guarantee events even in silence)
const curBar=Math.floor(K.bar); if(S.lastBar==null||curBar<S.lastBar)S.lastBar=curBar;
if(curBar>S.lastBar){ S.lastBar=curBar; const mag=0.5+0.6*K.intensity;
  if(act==='quake'){ if(curBar%2===0) jolt(mag*1.7,null); }
  else if(act!=='pulse') jolt(mag,null);
}
if(act==='pulse'){ const cb=Math.floor(K.beat); if(S.lastB2==null||cb<S.lastB2)S.lastB2=cb; if(cb>S.lastB2){ S.lastB2=cb; jolt(0.26+0.3*K.intensity,null); } }
// audio-driven jolt (stage): bass over threshold, cooldown
S.cd-=dt; if(A.bass>P.threshold && S.cd<=0){ jolt(0.5+A.bass*1.2,null); S.cd=0.11; }

// integrate spring (decay to rest — never continuous)
S.vx+=(-stiff*S.ox-damp*S.vx)*dt; S.vy+=(-stiff*S.oy-damp*S.vy)*dt;
S.ox+=S.vx*dt; S.oy+=S.vy*dt;
S.ox=clp(S.ox,-maxo,maxo); S.oy=clp(S.oy,-maxo,maxo);
const shakeMag=clp(Math.hypot(S.ox,S.oy)/(maxo+1e-6),0,1);
const activeShift=(Math.abs(S.ox)+Math.abs(S.oy))>0.5;
const tk=Math.floor(K.t*20);

// overscan capture + shifted redraw (real scene shakes; flat bed shows nothing — drawn FX carry motion)
if(activeShift){
  if(!S.snap||S.snapKey!==W+'x'+Hh){ S.snapKey=W+'x'+Hh; S.snap=createGraphics(W,Hh); S.snap.colorMode(S.snap.HSB,360,100,100,100); }
  S.snap.clear(); S.snap.drawingContext.drawImage(drawingContext.canvas,0,0,W,Hh);
  const m2=Math.max(Math.abs(S.ox),Math.abs(S.oy))+2, scl=1+(2*m2)/u;
  push(); translate(W/2+S.ox,Hh/2+S.oy); scale(scl); image(S.snap,-W/2,-Hh/2,W,Hh); pop();
  if(isGlitch){ blendMode(ADD); const gj=shakeMag*u*0.03; tint(0,85,100,34*amt); image(S.snap,gj,0,W,Hh); tint(180,85,100,34*amt); image(S.snap,-gj,0,W,Hh); noTint(); blendMode(BLEND); }
}

// continuous unstable-camera vignette — MOTION FLOOR (large area, real-time, never re-phases)
if(!S.vig||S.vigKey!==W+'x'+Hh){ S.vigKey=W+'x'+Hh; const g=createGraphics(W,Hh); g.colorMode(g.HSB,360,100,100,100); g.clear(); const ctx=g.drawingContext, r=Math.hypot(W,Hh)*0.6; const grd=ctx.createRadialGradient(W/2,Hh/2,r*0.3,W/2,Hh/2,r); grd.addColorStop(0,'rgba(0,0,0,0)'); grd.addColorStop(1,'rgba(0,0,0,1)'); ctx.fillStyle=grd; ctx.fillRect(0,0,W,Hh); S.vig=g; }
const vwx=(0.028+0.05*en)*W*Math.sin(K.t*0.53+0.3)+S.ox*1.4;
const vwy=(0.028+0.05*en)*Hh*Math.sin(K.t*0.47+1.1)+S.oy*1.4;
const vA=clp((24+30*en+18*amt)*(0.6+0.4*Math.sin(K.t*0.8))+42*shakeMag*amt,0,94);
tint(0,0,100,vA); image(S.vig,vwx*0.42,vwy*0.42); noTint();

// drifting grit specks (continuous own-marks; reinforce the floor)
const gN=Math.floor(28+90*dens); noStroke();
for(let i=0;i<gN;i++){
  const gx=frc(fr(i*1.7)+K.t*0.02*(0.5+fr(i))*spd)*W, gy=frc(fr(i*2.3)+K.t*0.015*(0.5+fr(i*3))*spd)*Hh, b=fr(i*4.1+tk);
  fill(md(P.hue,360),isXray?0:16,b<0.5?92:14,clp(18+40*b*en,0,72));
  const d=u*0.003*(1+b)*sc; rect(gx,gy,d,d);
}

// impact shockwave rings (event)
blendMode(ADD);
for(let i=S.rings.length-1;i>=0;i--){ const rg=S.rings[i]; rg.r+=dt*u*3.0*(0.6+rg.mag); rg.life-=dt*3.0; if(rg.life<=0){ S.rings.splice(i,1); continue; } const a=clp(rg.life*62*amt,0,82); noFill(); stroke(md(P.hue+(isXray?180:0),360),isSeismic?12:58,100,a); strokeWeight((1+3*rg.mag)*sc); circle(rg.x+S.ox,rg.y+S.oy,rg.r*2); }

// radial motion streaks in the shake direction (event)
if(shakeMag>0.05){
  const sN=Math.floor((6+20*dens)*shakeMag), dirA=Math.atan2(S.oy,S.ox);
  for(let i=0;i<sN;i++){ const a=dirA+(fr(i*3+tk)-0.5)*1.2, rr0=u*(0.08+0.5*fr(i*5)), len=u*0.12*shakeMag*sc*(0.5+fr(i*2)); const sx=cx+Math.cos(a)*rr0, sy=cy+Math.sin(a)*rr0; stroke(md(P.hue+(isXray?180:0),360),isSeismic?10:44,100,clp(50*shakeMag*amt,0,80)); strokeWeight((0.6+1.5*fr(i))*sc); line(sx,sy,sx+Math.cos(a)*len,sy+Math.sin(a)*len); }
}

// flashbulb: partial bright bloom at epicentre on hard hits (never full-frame invert)
if(isFlash && shakeMag>0.28){ noStroke(); fill(md(P.hue+30,360),12,100,clp(46*shakeMag*amt,0,70)); circle(cx+S.ox,cy+S.oy,u*(0.4+0.5*shakeMag)); }
blendMode(BLEND);

drawingContext.shadowBlur=0; noStroke(); noTint();
